"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([[74921],{33505:(e,n,o)=>{o.r(n),o.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>r,metadata:()=>t,toc:()=>h});const t=JSON.parse('{"type":"mdx","permalink":"/powerful-words","source":"@site/src/pages/powerful-words.md","title":"The Powerful Words | \u6fc0\u52b1\u81ea\u5df1\u7684\u8bdd","description":"Make the most of everyday. \u6bcf\u4e00\u5929\u90fd\u8981\u505a\u5230\u6700\u597d \ud83d\udcaa\ud83d\udcaa\ud83d\udcaa","frontMatter":{"title":"The Powerful Words | \u6fc0\u52b1\u81ea\u5df1\u7684\u8bdd","date":"2021-05-31T12:49:13.000Z","description":"Make the most of everyday. \u6bcf\u4e00\u5929\u90fd\u8981\u505a\u5230\u6700\u597d \ud83d\udcaa\ud83d\udcaa\ud83d\udcaa","tags":["\u540d\u8a00","\u594b\u6597"],"categories":"\u4e00\u8d77\u8bfb\u4e66\u5440","sticky":true},"unlisted":false}');var i=o(74848),s=o(28453);const r={title:"The Powerful Words | \u6fc0\u52b1\u81ea\u5df1\u7684\u8bdd",date:new Date("2021-05-31T12:49:13.000Z"),description:"Make the most of everyday. \u6bcf\u4e00\u5929\u90fd\u8981\u505a\u5230\u6700\u597d \ud83d\udcaa\ud83d\udcaa\ud83d\udcaa",tags:["\u540d\u8a00","\u594b\u6597"],categories:"\u4e00\u8d77\u8bfb\u4e66\u5440",sticky:!0},a="The Powerful Words | \u6fc0\u52b1\u81ea\u5df1\u7684\u8bdd",l={},h=[{value:"\u8d22\u5bcc",id:"\u8d22\u5bcc",level:2}];function d(e){const n={blockquote:"blockquote",h1:"h1",h2:"h2",header:"header",img:"img",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"the-powerful-words--\u6fc0\u52b1\u81ea\u5df1\u7684\u8bdd",children:"The Powerful Words | \u6fc0\u52b1\u81ea\u5df1\u7684\u8bdd"})}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:o(32014).A+"",width:"1440",height:"796"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Make the most of everyday.\n\u6bcf\u4e00\u5929\u90fd\u8981\u505a\u5230\u6700\u597d\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Your attitude, not your aptitude, will determine your altitude. \u2014\u2014 Zig Ziglar\n\u51b3\u5b9a\u4f60\u4eba\u751f\u9ad8\u5ea6\u7684\uff0c\u4e0d\u662f\u4f60\u7684\u624d\u80fd\uff0c\u800c\u662f\u4f60\u7684\u6001\u5ea6\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Grit is sticking with your future, day in, day out, not just for the week, not just for the month, but for years, and working really hard to make that future a reality."}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u771f\u6b63\u6709\u624d\u534e\u7684\u4eba\uff0c\u5f80\u5f80\u4e0d\u662f\u5929\u8d4b\u5f02\u7980\uff0c\u800c\u662f\u4e60\u60ef\u4e86\u52e4\u594b\u3002\u5982\u679c\u4f60\u7684\u624d\u534e\u914d\u4e0d\u4e0a\u68a6\u60f3\uff0c\u811a\u6b65\u8ddf\u4e0d\u4e0a\u76ee\u5149\uff0c\u6240\u6709\u7684\u4efb\u6027\u4e0d\u8fc7\u662f\u4e00\u5ff5\u5e7b\u60f3\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsxs)(n.p,{children:["\u4e00\u4e2a\u4eba\u53ea\u8981\u628a\u5fc3\u4e2d\u7684\u60f3\u6cd5\u79ef\u6781\u5730\u4ed8\u8bf8\u884c\u52a8\uff0c",(0,i.jsx)(n.strong,{children:"\u4f46\u884c\u597d\u4e8b\uff0c\u83ab\u95ee\u524d\u7a0b"}),"\uff0c\u4eba\u751f\u5c31\u4f1a\u6709\u65e0\u9650\u7684\u60ca\u559c\u548c\u53ef\u80fd\u3002"]}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u54ea\u6015\u5bf9\u81ea\u5df1\u7684\u4e00\u70b9\u5c0f\u5c0f\u7684\u514b\u5236\uff0c\u4e5f\u4f1a\u4f7f\u4eba\u53d8\u5f97\u5f3a\u800c\u6709\u529b\u3002\u2014\u2014 \u9ad8\u5c14\u57fa"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"You can't control your bedtime, not even your life. The problem is you know everything, but you're just lazy.\n\u4f60\u8fde\u4f60\u7761\u89c9\u7684\u65f6\u95f4\u90fd\u63a7\u5236\u4e0d\u4e86\uff0c\u66f4\u522b\u8bf4\u4f60\u7684\u4eba\u751f\u4e86\u3002\u95ee\u9898\u5c31\u5728\u4e8e\u4f60\u4ec0\u4e48\u90fd\u77e5\u9053\uff0c\u4f46\u4f60\u5c31\u662f\u61d2\u554a\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u5982\u679c\u4f60\u538b\u6291\u81ea\u5df1\uff0c\u4e0d\u60f3\u770b\u6e05\u4f60\u662f\u8c01\uff0c\u7ec8\u6709\u4e00\u5929\u547d\u8fd0\u4f1a\u903c\u7740\u4f60\u8ba4\u8bc6\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u8fdb\u6b65\u4e0d\u80fd\u88ab\u4e0d\u5e78\u6253\u5012\uff0c\u60f3\u4e0d\u88ab\u9057\u5fd8\u5f88\u7b80\u5355\uff0c\u90a3\u5c31\u662f\u8ba9\u4e16\u754c\u53d8\u5f97\u6bd4\u539f\u5148\u66f4\u597d\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"The significant problems we have cannot be solved at the same level of thinking with which we created them. \u2026 No problem can be solved from the same level of consciousness that created it. \u2014\u2014 Albert Einstein\n\u6240\u6709\u56f0\u96be\u7684\u95ee\u9898\uff0c\u7b54\u6848\u90fd\u5728\u53e6\u5916\u4e00\u4e2a\u5c42\u6b21\u4e0a\uff0c\u540c\u4e00\u5c42\u6b21\u7684\u95ee\u9898\uff0c\u5f88\u96be\u9760\u540c\u4e00\u5c42\u6b21\u7684\u601d\u8003\u6765\u89e3\u51b3\u3002\u2014\u2014 \u7231\u56e0\u65af\u5766"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u6211\u751f\u6765\u5c31\u662f\u9ad8\u5c71\u800c\u975e\u6eaa\u6d41\uff0c\u6211\u6b32\u4e8e\u7fa4\u5cf0\u4e4b\u5dc5\uff0c\u4fef\u89c6\u5e73\u5eb8\u7684\u6c9f\u58d1\uff0c\u6211\u751f\u6765\u5c31\u662f\u4eba\u6770\u800c\u975e\u8349\u82a5\uff0c\u6211\u7ad9\u5728\u4f1f\u4eba\u4e4b\u80a9\uff0c\u85d0\u89c6\u5351\u5fae\u7684\u61e6\u592b\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"There's a phrase in Buddhism, 'Beginner's mind.' It's wonderful to have a beginner's mind.\n\u4f5b\u6559\u4e2d\u6709\u4e00\u53e5\u8bdd\uff1a\u521d\u5b66\u8005\u7684\u5fc3\u6001\uff1b\u62e5\u6709\u521d\u5b66\u8005\u7684\u5fc3\u6001\u662f\u4ef6\u4e86\u4e0d\u8d77\u7684\u4e8b\u60c5\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Remembering that you are going to die is the best way I know to avoid the trap of thinking you have something to lose.\n\u8c28\u8bb0\u81ea\u5df1\u603b\u4f1a\u6b7b\u53bb\uff0c\u662f\u8ba9\u81ea\u5df1\u907f\u514d\u9677\u5165\u201c\u4eba\u751f\u6709\u6240\u5931\u201d\u601d\u8003\u7684\u6700\u4f73\u65b9\u6cd5\u3002"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:o(72482).A+"",width:"3840",height:"2160"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Your time is limited, so don't waste it living someone else's life. Don't be trapped by dogma - which is living with the results of other people's thinking. Don't let the noise of other's opinions drown out your own inner voice. And most important, have the courage to follow your heart and intuition. They somehow already know what you truly want to become. Everything else is secondary.\n\u4f60\u7684\u65f6\u95f4\u6709\u9650\uff0c\u6240\u4ee5\u4e0d\u8981\u4e3a\u522b\u4eba\u800c\u6d3b\u3002\u4e0d\u8981\u88ab\u6559\u6761\u6240\u9650\uff0c\u4e0d\u8981\u6d3b\u5728\u522b\u4eba\u7684\u89c2\u5ff5\u91cc\u3002\u4e0d\u8981\u8ba9\u522b\u4eba\u7684\u610f\u89c1\u5de6\u53f3\u81ea\u5df1\u5185\u5fc3\u7684\u58f0\u97f3\u3002\u6700\u91cd\u8981\u7684\u662f\uff0c\u52c7\u6562\u7684\u53bb\u8ffd\u968f\u81ea\u5df1\u7684\u5fc3\u7075\u548c\u76f4\u89c9\uff0c\u53ea\u6709\u81ea\u5df1\u7684\u5fc3\u7075\u548c\u76f4\u89c9\u624d\u77e5\u9053\u4f60\u81ea\u5df1\u7684\u771f\u5b9e\u60f3\u6cd5\uff0c\u5176\u4ed6\u4e00\u5207\u90fd\u662f\u6b21\u8981\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Your time is limited, so don't waste it living someone else's life.\u2026Don't let the noise of others' opinions drown out your own inner voice.\n\u4f60\u7684\u65f6\u95f4\u6709\u9650\uff0c\u4e0d\u8981\u6d6a\u8d39\u4e8e\u91cd\u590d\u522b\u4eba\u7684\u751f\u6d3b\u3002\u4e0d\u8981\u8ba9\u522b\u4eba\u7684\u89c2\u70b9\u6df9\u6ca1\u4e86\u4f60\u5185\u5fc3\u7684\u58f0\u97f3\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"The only way to do great work is to love what you do. If you haven't found it yet, keep looking. Don't settle. As with all matters of the heart, you'll know when you find it.\n\u6210\u5c31\u4e00\u756a\u4f1f\u4e1a\u7684\u552f\u4e00\u9014\u5f84\u5c31\u662f\u70ed\u7231\u81ea\u5df1\u7684\u4e8b\u4e1a\u3002\u5982\u679c\u4f60\u8fd8\u6ca1\u80fd\u627e\u5230\u8ba9\u81ea\u5df1\u70ed\u7231\u7684\u4e8b\u4e1a\uff0c\u7ee7\u7eed\u5bfb\u627e\uff0c\u4e0d\u8981\u653e\u5f03\u3002\u8ddf\u968f\u81ea\u5df1\u7684\u5fc3\uff0c\u603b\u6709\u4e00\u5929\u4f60\u4f1a\u627e\u5230\u7684\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"There is no shortcut to excellence. You will have to make the commitment to make excellence your priority. Use your talents, abilities, and skills in the best way possible and get ahead of others by giving that little extra. Live by a higher standard and pay attention to the details that really do make the difference. Excellence is not difficult - simply decide right now to give it your best shot - and you will be amazed with what life gives you back.\n\u6210\u529f\u6ca1\u6709\u6377\u5f84\u3002\u4f60\u5fc5\u987b\u628a\u5353\u8d8a\u8f6c\u53d8\u6210\u4f60\u8eab\u4e0a\u7684\u4e00\u4e2a\u7279\u8d28\u3002\u6700\u5927\u9650\u5ea6\u5730\u53d1\u6325\u4f60\u7684\u5929\u8d4b\u3001\u624d\u80fd\u3001\u6280\u5de7\uff0c\u628a\u5176\u4ed6\u6240\u6709\u4eba\u7529\u5728\u4f60\u540e\u9762\u3002\u9ad8\u6807\u51c6\u4e25\u683c\u81ea\u5df1\uff0c\u628a\u6ce8\u610f\u529b\u96c6\u4e2d\u5728\u90a3\u4e9b\u5c06\u4f1a\u6539\u53d8\u4e00\u5207\u7684\u7ec6\u8282\u4e0a\u3002\u53d8\u5f97\u5353\u8d8a\u5e76\u4e0d\u8270\u96be\u2014\u2014\u4ece\u73b0\u5728\u5f00\u59cb\u5c3d\u81ea\u5df1\u6700\u5927\u80fd\u529b\u53bb\u505a\u2014\u2014\u4f60\u4f1a\u53d1\u73b0\u751f\u6d3b\u5c06\u7ed9\u4f60\u60ca\u4eba\u7684\u56de\u62a5\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Innovation has no limits. The only limit is your imagination. It's time for you to begin thinking out of the box. If you are involved in a growing industry, think of ways to become more efficient; more customer friendly; and easier to do business with. If you are involved in a shrinking industry \u2013 get out of it quick and change before you become obsolete; out of work; or out of business. And remember that procrastination is not an option here. Start innovating now!\n\u521b\u65b0\u65e0\u6781\u9650\uff01\u53ea\u8981\u6562\u60f3\uff0c\u6ca1\u6709\u4ec0\u4e48\u4e0d\u53ef\u80fd\uff0c\u7acb\u5373\u8df3\u51fa\u601d\u7ef4\u7684\u6846\u6846\u5427\u3002\u5982\u679c\u4f60\u6b63\u5904\u4e8e\u4e00\u4e2a\u4e0a\u5347\u7684\u671d\u9633\u884c\u4e1a\uff0c\u90a3\u4e48\u5c1d\u8bd5\u53bb\u5bfb\u627e\u66f4\u6709\u6548\u7684\u89e3\u51b3\u65b9\u6848\uff1a\u66f4\u62db\u6d88\u8d39\u8005\u559c\u7231\u3001\u66f4\u7b80\u6d01\u7684\u5546\u4e1a\u6a21\u5f0f\u3002\u5982\u679c\u4f60\u5904\u4e8e\u4e00\u4e2a\u65e5\u6e10\u840e\u7f29\u7684\u884c\u4e1a\uff0c\u90a3\u4e48\u8d76\u7d27\u5728\u81ea\u5df1\u53d8\u5f97\u8ddf\u4e0d\u4e0a\u65f6\u4ee3\u4e4b\u524d\u62bd\u8eab\u800c\u51fa\uff0c\u53bb\u6362\u4e2a\u5de5\u4f5c\u6216\u8005\u8f6c\u6362\u884c\u4e1a\u3002\u4e0d\u8981\u62d6\u5ef6\uff0c\u7acb\u523b\u5f00\u59cb\u521b\u65b0\uff01"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Live in a way that is ethically responsible. Try to make a difference in this world and contribute to the higher good. You'll find it gives more meaning to your life and it's a great antidote to boredom. There is always so much to be done. And talk to others about what you are doing. Don't preach or be self-righteous, or fanatical about it, that just puts people off, but at the same time, don't be shy about setting an example, and use opportunities that arise to let others know what you are doing.\n\u5e26\u7740\u8d23\u4efb\u611f\u751f\u6d3b\uff0c\u5c1d\u8bd5\u4e3a\u8fd9\u4e2a\u4e16\u754c\u5e26\u6765\u70b9\u6709\u610f\u4e49\u7684\u4e8b\u60c5\uff0c\u4e3a\u66f4\u9ad8\u5c1a\u7684\u4e8b\u60c5\u505a\u70b9\u8d21\u732e\u3002\u8fd9\u6837\u4f60\u4f1a\u53d1\u73b0\u751f\u6d3b\u66f4\u52a0\u6709\u610f\u4e49\uff0c\u751f\u547d\u4e0d\u518d\u67af\u71e5\u3002\u9700\u8981\u6211\u4eec\u53bb\u505a\u7684\u4e8b\u60c5\u5f88\u591a\u3002\u544a\u8bc9\u5176\u4ed6\u4eba\u4f60\u7684\u8ba1\u5212\uff0c\u4e0d\u8981\u9f13\u5439\uff0c\u4e5f\u4e0d\u8981\u81ea\u4ee5\u4e3a\u662f\uff0c\u66f4\u4e0d\u80fd\u76f2\u76ee\u72c2\u70ed\uff0c\u90a3\u6837\u53ea\u4f1a\u628a\u4eba\u4eec\u5413\u8dd1\uff0c\u5f53\u7136\uff0c\u4f60\u4e5f\u4e0d\u8981\u5bb3\u6015\u6210\u4e3a\u699c\u6837\uff0c\u8981\u6293\u4f4f\u51fa\u5934\u7684\u673a\u4f1a\u8ba9\u4eba\u4eec\u77e5\u9053\u4f60\u7684\u6240\u4f5c\u6240\u4e3a\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"I've got it down to four words: \"Do what you love.\" Seek out an occupation that gives you a sense of meaning, direction and satisfaction in life. Having a sense of purpose and striving towards goals gives life meaning, direction and satisfaction. It not only contributes to health and longevity, but also makes you feel better in difficult times. Do you jump out of bed on Monday mornings and look forward to the work week? If the answer is 'no', keep looking, you'll know when you find it.\n\u201c\u6211\u628a\u8fd9\u6bb5\u8bdd\u6d53\u7f29\u4e3a\uff1a\u201c\u505a\u6211\u6240\u7231\u201d\u3002\u53bb\u5bfb\u627e\u4e00\u4e2a\u80fd\u7ed9\u4f60\u7684\u751f\u547d\u5e26\u6765\u610f\u4e49\u3001\u4ef7\u503c\u548c\u8ba9\u4f60\u611f\u89c9\u5145\u5b9e\u7684\u4e8b\u4e1a\u3002\u62e5\u6709\u4f7f\u547d\u611f\u548c\u76ee\u6807\u611f\u624d\u80fd\u7ed9\u751f\u547d\u5e26\u6765\u610f\u4e49\u3001\u4ef7\u503c\u548c\u5145\u5b9e\u3002\u8fd9\u4e0d\u4ec5\u5bf9\u4f60\u7684\u5065\u5eb7\u548c\u5bff\u547d\u6709\u76ca\u5904\uff0c\u800c\u4e14\u5373\u4f7f\u5728\u4f60\u5904\u4e8e\u56f0\u5883\u7684\u65f6\u5019\u4f60\u4e5f\u4f1a\u611f\u89c9\u826f\u597d\u3002\u5728\u6bcf\u5468\u4e00\u7684\u65e9\u4e0a\uff0c\u4f60\u80fd\u4e0d\u80fd\u5229\u7d22\u7684\u722c\u8d77\u6765\u5e76\u4e14\u5bf9\u5de5\u4f5c\u65e5\u5145\u6ee1\u671f\u5f85\uff1f\u5982\u679c\u4e0d\u80fd\uff0c\u90a3\u4e48\u4f60\u5f97\u91cd\u65b0\u53bb\u5bfb\u627e\u3002\u4f60\u4f1a\u611f\u89c9\u5f97\u5230\u4f60\u662f\u4e0d\u662f\u771f\u7684\u627e\u5230\u4e86\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Did you know that you have big things to accomplish in life? And did you know that those big things are getting rather dusty while you pour yourself another cup of coffee, and decide to mull things over rather than do them? We were all born with a gift to give in life, one which informs all of our desires, interests, passions and curiosities. This gift is, in fact, our purpose. And you don't need permission to decide your own purpose. No boss, teacher, parent, priest or other authority can decide this for you. Just find that unique purpose.\n\u4f60\u662f\u5426\u77e5\u9053\u5728\u4f60\u7684\u751f\u547d\u4e2d\uff0c\u6709\u4ec0\u4e48\u4f7f\u547d\u662f\u4e00\u5b9a\u8981\u8fbe\u6210\u7684\uff1f\u4f60\u77e5\u4e0d\u77e5\u9053\u5728\u4f60\u559d\u4e00\u676f\u5496\u5561\u6216\u8005\u505a\u4e9b\u65e0\u610f\u4e49\u4e8b\u60c5\u7684\u65f6\u5019\uff0c\u8fd9\u4e9b\u4f7f\u547d\u53c8\u8499\u4e0a\u4e86\u4e00\u5c42\u7070\u5c18\uff1f\u6211\u4eec\u751f\u6765\u5c31\u968f\u8eab\u5e26\u7740\u4e00\u4ef6\u4e1c\u897f\uff0c\u8fd9\u4ef6\u4e1c\u897f\u6307\u793a\u7740\u6211\u4eec\u7684\u6e34\u671b\u3001\u5174\u8da3\u3001\u70ed\u60c5\u4ee5\u53ca\u597d\u5947\u5fc3\uff0c\u8fd9\u5c31\u662f\u4f7f\u547d\u3002\u4f60\u4e0d\u9700\u8981\u4efb\u4f55\u6743\u5a01\u6765\u8bc4\u65ad\u4f60\u7684\u4f7f\u547d\uff0c\u6ca1\u6709\u4efb\u4f55\u8001\u677f\u3001\u8001\u5e08\u3001\u7236\u6bcd\u3001\u7267\u5e08\u4ee5\u53ca\u4efb\u4f55\u6743\u5a01\u53ef\u4ee5\u5e2e\u4f60\u6765\u51b3\u5b9a\u3002\u4f60\u9700\u8981\u9760\u4f60\u81ea\u5df1\u6765\u5bfb\u627e\u8fd9\u4e2a\u72ec\u7279\u7684\u4f7f\u547d\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Stay hungry, Stay foolish."}),"\n\u6c42\u77e5\u82e5\u6e34\uff0c\u865a\u6000\u82e5\u611a\u3002\n\u6ce8\u89e3\uff1a\u4fdd\u6301\u9965\u997f\uff0c\u8981\u6709\u4e00\u9897\u597d\u5b66\u3001\u597d\u5947\u7684\u5fc3\uff0c\u8981\u5982\u9965\u4f3c\u6e34\u5730\u5b66\u4e60\uff0c\u540c\u65f6\u8981\u6709\u7a7a\u676f\u5fc3\u6001\uff0c\u65f6\u523b\u6e05\u96f6\uff0c\u4fdd\u6301\u521d\u5b66\u8005\u7684\u5b66\u4e60\u5fc3\u6001\u3002"]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:o(66341).A+"",width:"1838",height:"1012"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Intelligence is the ability to avoid doing work, yet getting the work done. \u2014\u2014 Linus Torvalds\n\u806a\u660e\u662f\u4e00\u79cd\u514d\u4e8e\u5de5\u4f5c\uff0c\u5374\u53c8\u80fd\u628a\u5de5\u4f5c\u5b8c\u6210\u7684\u80fd\u529b\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u5141\u8bb8\u81ea\u5df1\u68c0\u8ba8\u81ea\u5df1\uff0c\u751f\u547d\u5c31\u4f1a\u5f00\u59cb\u6539\u53d8\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u4eba\u751f\u6700\u5927\u7684\u98ce\u9669\uff0c\u5c31\u662f\u4ece\u4e0d\u5192\u9669\u3002"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u6709\u52c7\u6c14\u79bb\u5f00\u6d77\u5cb8\uff0c\u624d\u80fd\u53d1\u73b0\u65b0\u6d77\u6d0b\u3002\u2014\u2014 \u7f8e\u56fd\u4f5c\u5bb6\u4e39\u5c3c\u5c14\u2027\u4e9a\u4f2f\u62c9\u7f55\uff08Daniel Abraham\uff09"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u4ece\u5c0f\u6211\u7236\u6bcd\u5c31\u4e00\u76f4\u9f13\u52b1\u6211\u53bb\u8ffd\u6211\u7684\u68a6\u60f3\u3002\u4ed6\u4eec\u4f1a\u8bf4\uff1a\u201c\u5927\u4e0d\u4e86\u5c31\u662f\u4f60\u4e0d\u6210\u529f\uff0c\u4f46\u662f\u4e0d\u80fd\u4e0d\u53bb\u8ffd\u6c42\u4f60\u7684\u68a6\u60f3\u3002\u4e0d\u80fd\u653e\u5f03\uff0c\u53bb\u8bd5\u8bd5\u770b\u3002\u201d \u2014\u2014 JeremyLin \u6797\u4e66\u8c6a"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:o(42002).A+"",width:"3072",height:"2048"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:'"You got a dream, you gotta protect it. people can\u2019t do something themselves, they wanna tell you you can\u2019t do it. If you want something, go get it."\n\u4e0d\u8981\u5225\u4eba\u544a\u8bc9\u4f60\u8be5\u505a\u4ec0\u4e48\uff0c\u6709\u68a6\u60f3\uff0c\u5c31\u81ea\u5df1\u53bb\u4fdd\u62a4\u3002\u522b\u4eba\u505a\u4e0d\u6210\u4ec0\u4e48\u4e8b\u60c5\uff0c\u5c31\u4f1a\u8ddf\u4f60\u8bf4\u4f60\u4e5f\u505a\u4e0d\u6210\u3002\u5982\u679c\u4f60\u60f3\u8981\u4ec0\u4e48\uff0c\u5c31\u8981\u53bb\u4e89\u53d6\uff01 \u2014\u2014\u300a\u5f53\u5e78\u798f\u6765\u6572\u95e8\u300b'}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u5982\u679c\u6709\u4e00\u5929\uff1a\u4f60\u4e0d\u518d\u5bfb\u627e\u7231\u60c5\uff0c\u53ea\u662f\u53bb\u7231\uff1b\u4f60\u4e0d\u518d\u6e34\u671b\u6210\u529f\uff0c\u53ea\u662f\u53bb\u505a\uff1b\u4f60\u4e0d\u518d\u8ffd\u6c42\u7a7a\u6cdb\u7684\u6210\u957f\uff0c\u53ea\u662f\u5f00\u59cb\u4fee\u517b\u81ea\u5df1\u7684\u6027\u60c5\uff1b\u4f60\u7684\u4eba\u751f\u4e00\u5207\uff0c\u624d\u771f\u6b63\u5f00\u59cb\u3002\u2014\u2014 \u7eaa\u4f2f\u4f26"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u547d\u5b9a\u7684\u5c40\u9650\u5c3d\u53ef\u6c38\u5728\uff0c\u4e0d\u5c48\u7684\u6311\u6218\u5374\u4e0d\u53ef\u987b\u81fe\u6216\u7f3a\u3002\u2014\u2014 \u53f2\u94c1\u751f"}),"\n"]}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"\u5de5\u4f5c\u662f\u4e3a\u4e86\u66f4\u79ef\u6781\u5730\u751f\u6d3b\uff0c\u5982\u679c\u53d8\u6210\u8d1f\u62c5\uff0c\u90a3\u5c31\u6362\u4e00\u79cd\u6d3b\u6cd5\u3002\u4e0d\u8981\u628a\u751f\u547d\u732e\u7ed9\u65e0\u77e5\u3001\u5e73\u5eb8\u548c\u4f4e\u4fd7\uff0c\u5de5\u4f5c\u672c\u6765\u5c31\u662f\u4e2a\u6109\u5feb\u3001\u6709\u610f\u4e49\u7684\u4e8b\u60c5\u3002"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:o(49693).A+"",width:"630",height:"422"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Why do we work so hard? For money? For fame? I think the reason that we work so hard, is that we want to see a bigger world. We want to choose our own friends and environment, and we want the best for our family. But most of all, we want to be a better version of ourselves."}),"\n",(0,i.jsx)(n.p,{children:"\u6211\u4eec\u4e3a\u4ec0\u4e48\u52aa\u529b\u5de5\u4f5c\uff1f\u4e3a\u4e86\u94b1\uff1f\u4e3a\u4e86\u540d\u58f0\uff1f\u6211\u8ba4\u4e3a\u6211\u4eec\u5982\u6b64\u52aa\u529b\u5de5\u4f5c\u7684\u539f\u56e0\uff0c\u662f\u56e0\u4e3a\u6211\u4eec\u60f3\u770b\u5230\u4e00\u4e2a\u66f4\u5927\u7684\u4e16\u754c\u3002\u6211\u4eec\u8981\u9009\u62e9\u6211\u4eec\u7684\u670b\u53cb\u548c\u73af\u5883\uff0c\u60f3\u7ed9\u6211\u4eec\u5bb6\u4eba\u63d0\u4f9b\u66f4\u597d\u7684\u3002\u4f46\u6700\u91cd\u8981\u7684\u662f\uff0c\u6211\u4eec\u60f3\u6210\u4e3a\u66f4\u597d\u7684\u81ea\u5df1\u3002"}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"\u8d22\u5bcc",children:"\u8d22\u5bcc"}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"The first million is hard, but the second million is inevitable. It's not becoming a millionaire that's important, it's the person that you must become in order to become a millionaire. You have to become a completely different person, you have to develop character beyond 99 percent of the people in the world, you have to develop honesty and discipline and quality relationships, and the willingness and the ability to work and set priorities and all kinds of stuff."}),"\n",(0,i.jsx)(n.p,{children:"\u8d5a\u5230\u7b2c\u4e00\u4e2a\u4e00\u767e\u4e07\u662f\u76f8\u5f53\u56f0\u96be\u7684\uff0c\u4f46\u7b2c\u4e8c\u4e2a\u4e00\u767e\u4e07\u5c31\u662f\u6c34\u5230\u6e20\u6210\u7684\u4e8b\u4e86\u3002\u91cd\u8981\u7684\u4e0d\u662f\u6210\u4e3a\u767e\u4e07\u5bcc\u7fc1\uff0c\u800c\u662f\u4f60\u5fc5\u987b\u6210\u4e3a\u4ec0\u4e48\u6837\u7684\u4eba\u624d\u80fd\u6210\u4e3a\u767e\u4e07\u5bcc\u7fc1\u3002\u4f60\u8981\u6210\u4e3a\u4e00\u4e2a\u4e0e\u4f17\u4e0d\u540c\u7684\u4eba\uff0c\u4f60\u5fc5\u987b\u8981\u53d1\u5c55\u51fa\u8d85\u8fc7\u4e16\u754c\u4e0a 99% \u7684\u4eba\u7684\u7279\u8d28\uff0c\u4f60\u5fc5\u987b\u57f9\u517b\u8bda\u5b9e\u3001\u81ea\u5f8b\u548c\u9ad8\u8d28\u91cf\u7684\u4eba\u9645\u5173\u7cfb\uff0c\u4ee5\u53ca\u52aa\u529b\u7684\u610f\u613f\u548c\u5de5\u4f5c\u80fd\u529b\u5e76\u4e14\u8bbe\u7f6e\u4f18\u5148\u7ea7\u7b49\u7b49\u8fd9\u4e00\u5207\u4e1c\u897f\u3002"}),"\n"]})]})}function c(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},42002:(e,n,o)=>{o.d(n,{A:()=>t});const t=o.p+"assets/images/JeremyLin-64898fab0cb87ef98e5f39cccc5d69e7.jpg"},66341:(e,n,o)=>{o.d(n,{A:()=>t});const t=o.p+"assets/images/Stay-hungry-Stay-foolish-b1eb72595edfb44a8489ed93fa69f152.png"},72482:(e,n,o)=>{o.d(n,{A:()=>t});const t=o.p+"assets/images/beginner-s-mind-d30856c2b3093b3cee3e7ff28886e7c5.jpg"},32014:(e,n,o)=>{o.d(n,{A:()=>t});const t=o.p+"assets/images/cover-001-ca886bf60c40a8d0f354468919a6c20c.jpg"},49693:(e,n,o)=>{o.d(n,{A:()=>t});const t=o.p+"assets/images/dont-stop-running-30ecb039c83466905e6bf341127ee429.jpg"},28453:(e,n,o)=>{o.d(n,{R:()=>r,x:()=>a});var t=o(96540);const i={},s=t.createContext(i);function r(e){const n=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);